package org.jlinalg.cli;
import static org.junit.jupiter.api.Assertions.*;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class FumaCelltypeCliTest {
    @TempDir Path temp;
    private int run(Map<String,String> options){var args=new ArrayList<>(List.of("--method","cell-type"));options.forEach((k,v)->args.addAll(List.of("--"+k,v)));return FumaToolsCli.run(args.toArray(String[]::new),new PrintStream(new ByteArrayOutputStream()),new PrintStream(new ByteArrayOutputStream()));}
    private String warning(Map<String,String> options)throws Exception{return Files.readString(Path.of(options.get("out")).resolve("WARNINGS.md"));}
    @Test void missingRuntimeSkipsWithProminentCauseRecoveryAndPartialLedger()throws Exception {var o=FumaCelltypeTestData.options(temp);assertEquals(3,run(o));assertTrue(warning(o).startsWith("# ANALYSIS SKIPPED"));assertTrue(warning(o).contains("Required action"));assertTrue(warning(o).contains("install_magma.py"));assertTrue(Files.exists(temp.resolve("result/partial/resource-coverage.tsv")));assertFalse(Files.exists(temp.resolve("result/step1.tsv")));assertTrue(Files.readString(temp.resolve("result/analysis-status.json")).contains("skipped-dependency-unavailable"));}
    @Test void invalidCorrectionIsFailureRatherThanRuntimeSkip()throws Exception {var o=FumaCelltypeTestData.options(temp);o.put("correction","none");assertEquals(2,run(o));assertTrue(warning(o).contains("--correction must be"));}
    @Test void explicitStepFlagsAndNestingAreRequired()throws Exception {var o=FumaCelltypeTestData.options(temp);o.put("step2","false");assertEquals(2,run(o));assertTrue(warning(o).contains("--step3 true requires --step2 true"));o.put("out",temp.resolve("flags").toString());o.put("step2","yes");assertEquals(2,run(o));assertTrue(warning(o).contains("explicit true or false"));}
    @Test void unsupportedRuntimeProfileCannotBeSilentlySubstituted()throws Exception {var o=FumaCelltypeTestData.options(temp);o.put("runtime-profile","linux");assertEquals(2,run(o));assertTrue(warning(o).contains("explicit admitted"));}
    @Test void badMissingnessAndResourceCapacitiesFailWithNamedCause()throws Exception {var o=FumaCelltypeTestData.options(temp);o.put("missing-values","mean");assertEquals(2,run(o));assertTrue(warning(o).contains("error or source-default"));o.put("out",temp.resolve("budget").toString());o.put("missing-values","error");o.put("max-values","5");assertEquals(2,run(o));assertTrue(warning(o).contains("--max-values"));}
    @Test void tamperedGeneBundleIsNotAdmitted()throws Exception {var o=FumaCelltypeTestData.options(temp);Files.writeString(Path.of(o.get("gene-bundle")).resolve("genes.raw"),"changed");assertEquals(2,run(o));assertTrue(warning(o).contains("bundle member changed"));}
    @Test void missingAverageAndMalformedPropertiesProduceRetainedFailure()throws Exception {var o=FumaCelltypeTestData.options(temp);Files.writeString(temp.resolve("properties.tsv"),"GENE\tCellA\tMean\nE1\t1\t2\n");assertEquals(2,run(o));assertTrue(warning(o).contains("exact precomputed Average"));assertFalse(Files.exists(temp.resolve("result/step1.tsv")));}
    @Test void existingOutputIsPreserved()throws Exception {var o=FumaCelltypeTestData.options(temp);Path out=Path.of(o.get("out"));Files.createDirectory(out);Files.writeString(out.resolve("marker"),"keep");assertEquals(2,run(o));assertEquals("keep",Files.readString(out.resolve("marker")));}
    @Test void unicodeResourcesUseAnAsciiJsonCarrierAndInputsStayUnchanged()throws Exception {var o=FumaCelltypeTestData.options(temp);Path folder=temp.resolve("resources Ω");Files.createDirectory(folder);Path properties=folder.resolve("expression µ.tsv");Files.move(temp.resolve("properties.tsv"),properties);Files.writeString(temp.resolve("datasets.tsv"),"dataset\tresource_id\tpath\nDataA\tresource µ\tresources Ω/expression µ.tsv\n");o.put("datasets","datasets.tsv");o.put("gene-bundle","gene-bundle");o.put("home","missing-runtime");o.put("out","carrier-result");Files.writeString(temp.resolve("options.json"),RegenieRuntime.json(o));int code=FumaToolsCli.run(new String[]{"--celltype-options-file",temp.resolve("options.json").toString()},new PrintStream(new ByteArrayOutputStream()),new PrintStream(new ByteArrayOutputStream()));assertEquals(3,code);assertTrue(Files.exists(temp.resolve("carrier-result/partial/prepared/d0001.properties.tsv")));assertTrue(Files.readString(properties).contains("E1\t1\t.1"));}
    @Test void unicodeFittingOutputParentHasAnActionablePrelaunchFailure()throws Exception {var o=FumaCelltypeTestData.options(temp);o.put("out",temp.resolve("parent Ω/result").toString());assertEquals(2,run(o));assertTrue(warning(o).contains("ASCII output parent path"));o.put("out",temp.resolve("final-name Ω").toString());assertEquals(3,run(o));assertTrue(Files.exists(temp.resolve("final-name Ω/partial/resource-coverage.tsv")));}
    @Test void recursiveUnknownAndNonStringRecipeOptionsFail()throws Exception {for(String text:List.of("{\"unknown\":\"x\"}","{\"celltype-options-file\":\"x\"}","{\"timeout\":1}")){Files.writeString(temp.resolve("bad.json"),text);assertEquals(2,FumaToolsCli.run(new String[]{"--celltype-options-file",temp.resolve("bad.json").toString()},new PrintStream(new ByteArrayOutputStream()),new PrintStream(new ByteArrayOutputStream())));}}
    @Test void invalidManagedHomeIsPreservedAndClassifiedUnavailable()throws Exception {var o=FumaCelltypeTestData.options(temp);Path home=Path.of(o.get("home"));Files.createDirectory(home);Files.writeString(home.resolve(".jlinalg-magma.json"),"{}");assertEquals(3,run(o));assertEquals("{}",Files.readString(home.resolve(".jlinalg-magma.json")));assertTrue(warning(o).contains("MAGMA"));}
    @Test void typedParentPropagatesRuntimeSkipAndStageWarnings()throws Exception {var o=FumaCelltypeTestData.options(temp);var stage=new LinkedHashMap<>(o);stage.remove("out");stage.remove("build");Path recipe=temp.resolve("workflow.json");Files.writeString(recipe,RegenieRuntime.json(Map.of("schema_version",1,"build","fixture-build","out","parent","cell_type",stage)));assertEquals(3,FumaToolsCli.run(new String[]{"--workflow-options-file",recipe.toString()},new PrintStream(new ByteArrayOutputStream()),new PrintStream(new ByteArrayOutputStream())));assertTrue(Files.readString(temp.resolve("parent/cell-type/WARNINGS.md")).contains("Required action"));assertTrue(Files.readString(temp.resolve("parent/manifest.json")).contains("partially-skipped"));}
    @Test void connectedParentGeneBundleOverrideIsRejected()throws Exception {var o=FumaCelltypeTestData.options(temp);o.remove("out");o.remove("build");Files.writeString(temp.resolve("bad-parent.json"),RegenieRuntime.json(Map.of("schema_version",1,"build","fixture-build","out","parent","cell_type",o,"magma_gene",Map.of("model","mean"))));assertEquals(2,FumaToolsCli.run(new String[]{"--workflow-options-file",temp.resolve("bad-parent.json").toString()},new PrintStream(new ByteArrayOutputStream()),new PrintStream(new ByteArrayOutputStream())));assertFalse(Files.exists(temp.resolve("parent")));}
    @Test void helpAndMissingRequiredOptionsExplainRecovery()throws Exception {var output=new ByteArrayOutputStream();assertEquals(0,FumaToolsCli.run(new String[]{"--method","cell-type","--help"},new PrintStream(output),new PrintStream(output)));assertTrue(output.toString().contains("gene-coverage"));output.reset();assertEquals(2,FumaToolsCli.run(new String[]{"--method","cell-type"},new PrintStream(output),new PrintStream(output)));assertTrue(output.toString().contains("Required action"));}
}
